#pragma once

#include "Basic.hpp"

#include "FortAudioClustersRuntime_classes.hpp"
#include "FortAudioClustersRuntime_parameters.hpp"

namespace SDK
{

void UGameFeatureAction_AddAudioCluster::HandleRegisteredActorDeath(float Damage, const struct FGameplayTagContainer& DamageTags, const struct FVector& Momentum, const struct FHitResult& HitInfo, class AFortPawn* InstigatedBy, class AActor* DamageCauser, const struct FGameplayEffectContextHandle& EffectContext)
{
	static class UFunction* Func = nullptr;

	if (Func == nullptr)
		Func = Class->GetFunction("GameFeatureAction_AddAudioCluster", "HandleRegisteredActorDeath");

	Params::GameFeatureAction_AddAudioCluster_HandleRegisteredActorDeath Parms{};

	Parms.Damage = Damage;
	Parms.DamageTags = std::move(DamageTags);
	Parms.Momentum = std::move(Momentum);
	Parms.HitInfo = std::move(HitInfo);
	Parms.InstigatedBy = InstigatedBy;
	Parms.DamageCauser = DamageCauser;
	Parms.EffectContext = std::move(EffectContext);

	auto Flgs = Func->FunctionFlags;
	Func->FunctionFlags |= 0x400;

	UObject::ProcessEvent(Func, &Parms);

	Func->FunctionFlags = Flgs;
}

}
